import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;
    static long n;
    static int m;

    static long[][] multiply(long[][] one, long[][] two) {
        long[][] result = new long[m][m];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < m; k++) {
                    result[i][j] = (result[i][j] + one[i][k] * two[k][j] % MOD) % MOD;
                }
            }
        }

        return result;
    }

    static long[][] power(long exp, long[][] base) {
        if (exp == 1) {
            return base;
        }

        long[][] result = power(exp / 2, base);
        result = multiply(result, result);

        if ((exp & 1) == 1) {
            result = multiply(result, base);
        }

        return result;
    }

    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        n = scanner.nextLong();
        m = (int) scanner.nextLong();

        if (n < m) {
            System.out.print("1");
            return;
        }

        if (n == m) {
            System.out.print("2");
            return;
        }

        long[][] matrix = new long[m][m];
        matrix[0][0] = 1;
        matrix[0][m - 1] = 1;

        for (int i = 1; i < m; i++) {
            matrix[i][i - 1] = 1;
        }

        System.out.println(power(n, matrix)[0][0]);
    }

    static class FastScanner {
        private final InputStream input;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer;
        private int length;

        FastScanner(InputStream input) {
            this.input = input;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = input.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }
    }
}

